CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS server_state(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','user')),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(digest TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites(digest TEXT PRIMARY KEY,expires_at INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,until_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS documents(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,id TEXT NOT NULL,payload BLOB NOT NULL,revision INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(user_id,kind,id));
CREATE TABLE IF NOT EXISTS connections(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider TEXT NOT NULL,athlete_id TEXT NOT NULL,tokens BLOB NOT NULL,scope TEXT NOT NULL,connected_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'connected',last_sync INTEGER,error TEXT,next_sync INTEGER NOT NULL DEFAULT 0,preferences TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(user_id,provider),UNIQUE(provider,athlete_id));
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,challenge TEXT NOT NULL,scopes TEXT NOT NULL,expires_at INTEGER NOT NULL,handoff_digest TEXT,status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS cache(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider TEXT NOT NULL,kind TEXT NOT NULL,id TEXT NOT NULL,payload BLOB NOT NULL,synced_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(user_id,provider,kind,id));
CREATE TABLE IF NOT EXISTS cursors(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider TEXT NOT NULL,kind TEXT NOT NULL,cursor INTEGER NOT NULL,PRIMARY KEY(user_id,provider,kind));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider TEXT NOT NULL,kind TEXT NOT NULL,job_key TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,error TEXT,result BLOB,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(user_id,provider,kind,job_key));
CREATE TABLE IF NOT EXISTS sync_history(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider TEXT NOT NULL,status TEXT NOT NULL,message TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quota(provider TEXT PRIMARY KEY,next_at INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS jobs_due ON jobs(status,next_at);
CREATE INDEX IF NOT EXISTS cache_expiry ON cache(expires_at);
